func foreverFillArmor(items []*proto.SimItem) {
	for _, it := range items {
		a, ok := foreverMissingArmor[it.Id]
		if !ok {
			continue
		}
		for _, so := range it.ScalingOptions {
			if so == nil {
				continue
			}
			if so.Stats == nil {
				so.Stats = map[int32]float64{}
			}
			if so.Stats[int32(proto.Stat_StatArmor)] == 0 && so.Stats[int32(proto.Stat_StatBonusArmor)] == 0 {
				so.Stats[int32(proto.Stat_StatBonusArmor)] = a
			}
		}
	}
}
